import{_ as d}from"./chunks/prontera-guild.BuH2I_WE.js";import{c as a,Q as r,j as e,m as l}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"PvP竞技场与对战系统","description":"RO3 PvP竞技场玩法详解，含1v1、3v3、开放世界PVP模式，竞技场排名与奖励。","frontmatter":{"title":"PvP竞技场与对战系统","description":"RO3 PvP竞技场玩法详解，含1v1、3v3、开放世界PVP模式，竞技场排名与奖励。","lastUpdated":true},"headers":[],"relativePath":"guide/pvp-arena.md","filePath":"guide/pvp-arena.md","lastUpdated":1780230058000}'),o={name:"guide/pvp-arena.md"};function h(i,t,n,s,P,b){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="pvp竞技场与对战系统" tabindex="-1">PvP竞技场与对战系统 <a class="header-anchor" href="#pvp竞技场与对战系统" aria-label="Permalink to &quot;PvP竞技场与对战系统&quot;">​</a></h1><p><img src="'+d+'" alt="RO3 骑士公会"></p><p>除了大规模GVG攻城战外，RO3还提供了多种小规模PvP玩法，让玩家在不同场景中体验对抗乐趣。</p><h2 id="pvp模式一览" tabindex="-1">PvP模式一览 <a class="header-anchor" href="#pvp模式一览" aria-label="Permalink to &quot;PvP模式一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>规模</th><th>说明</th><th>开放时间</th></tr></thead><tbody><tr><td>竞技场1v1</td><td>单人</td><td>公平对决，纯技术较量</td><td>全天开放</td></tr><tr><td>竞技场3v3</td><td>小队</td><td>三人组队战术对抗</td><td>全天开放</td></tr><tr><td>开放世界PVP</td><td>无限制</td><td>特定地图自由PK</td><td>指定时段</td></tr><tr><td>GVG攻城战</td><td>100v100</td><td>公会大规模团战</td><td>每周三、六</td></tr><tr><td>领土争夺战</td><td>公会联盟</td><td>多公会领地争夺</td><td>每周日</td></tr></tbody></table><h2 id="竞技场1v1" tabindex="-1">竞技场1v1 <a class="header-anchor" href="#竞技场1v1" aria-label="Permalink to &quot;竞技场1v1&quot;">​</a></h2><h3 id="基本规则" tabindex="-1">基本规则 <a class="header-anchor" href="#基本规则" aria-label="Permalink to &quot;基本规则&quot;">​</a></h3><ul><li><strong>等级匹配</strong>：按等级区间匹配对手</li><li><strong>装备平衡</strong>：提供标准装备模板（可选）</li><li><strong>时间限制</strong>：每场5分钟</li><li><strong>胜负判定</strong>：击杀对方/时间到血量百分比高者胜</li></ul><h3 id="职业1v1强度排行-推测" tabindex="-1">职业1v1强度排行（推测） <a class="header-anchor" href="#职业1v1强度排行-推测" aria-label="Permalink to &quot;职业1v1强度排行（推测）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>梯队</th><th>职业</th><th>优势</th></tr></thead><tbody><tr><td>S</td><td>刺客</td><td>高爆发、隐身偷袭</td></tr><tr><td>A</td><td>巫师</td><td>远程压制、控制技能</td></tr><tr><td>A</td><td>猎人</td><td>风筝战术、陷阱控制</td></tr><tr><td>B</td><td>骑士</td><td>高生存、磨血战术</td></tr><tr><td>B</td><td>牧师</td><td>无限续航、消耗战</td></tr><tr><td>C</td><td>商人</td><td>1v1能力最弱</td></tr></tbody></table><h3 id="_1v1技巧" tabindex="-1">1v1技巧 <a class="header-anchor" href="#_1v1技巧" aria-label="Permalink to &quot;1v1技巧&quot;">​</a></h3><ol><li><strong>了解对手职业</strong>：不同职业有不同应对策略</li><li><strong>技能预判</strong>：观察对方动作预判技能</li><li><strong>走位拉扯</strong>：近战贴脸、远程保持距离</li><li><strong>技能循环</strong>：不要一键甩光所有技能</li></ol><h2 id="竞技场3v3" tabindex="-1">竞技场3v3 <a class="header-anchor" href="#竞技场3v3" aria-label="Permalink to &quot;竞技场3v3&quot;">​</a></h2><h3 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阵容类型</th><th>配置</th><th>说明</th></tr></thead><tbody><tr><td>铁三角</td><td>坦克+治疗+输出</td><td>最稳阵容，容错率高</td></tr><tr><td>双输出+治疗</td><td>输出x2+治疗</td><td>爆发高，考验治疗</td></tr><tr><td>三输出</td><td>输出x3</td><td>纯暴力，看谁先秒谁</td></tr><tr><td>控制流</td><td>巫师+猎人+刺客</td><td>控制链秒人</td></tr></tbody></table><h3 id="_3v3战术" tabindex="-1">3v3战术 <a class="header-anchor" href="#_3v3战术" aria-label="Permalink to &quot;3v3战术&quot;">​</a></h3><ol><li><strong>集火目标</strong>：优先击杀治疗/脆皮输出</li><li><strong>控制链</strong>：先手控制 → 爆发输出 → 收割</li><li><strong>保护治疗</strong>：治疗是3v3的核心</li><li><strong>地形利用</strong>：利用障碍物规避伤害</li></ol><h2 id="开放世界pvp" tabindex="-1">开放世界PVP <a class="header-anchor" href="#开放世界pvp" aria-label="Permalink to &quot;开放世界PVP&quot;">​</a></h2><h3 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h3><ul><li><strong>PVP地图</strong>：特定野外地图开放自由PK</li><li><strong>安全区</strong>：主城和低级地图不可PK</li><li><strong>惩罚机制</strong>：击杀普通玩家会扣除声望值</li><li><strong>悬赏系统</strong>：击杀红名玩家可获得奖励</li></ul><h3 id="pvp地图分级" tabindex="-1">PVP地图分级 <a class="header-anchor" href="#pvp地图分级" aria-label="Permalink to &quot;PVP地图分级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级段</th><th>PVP地图</th><th>说明</th></tr></thead><tbody><tr><td>30-60</td><td>妙勒尼山脉</td><td>低风险PVP</td></tr><tr><td>60-80</td><td>古城外围</td><td>中风险PVP</td></tr><tr><td>80-99</td><td>古城深处</td><td>高风险、高回报</td></tr></tbody></table><h2 id="竞技场奖励" tabindex="-1">竞技场奖励 <a class="header-anchor" href="#竞技场奖励" aria-label="Permalink to &quot;竞技场奖励&quot;">​</a></h2><h3 id="赛季奖励" tabindex="-1">赛季奖励 <a class="header-anchor" href="#赛季奖励" aria-label="Permalink to &quot;赛季奖励&quot;">​</a></h3><table tabindex="0"><thead><tr><th>排名段位</th><th>奖励</th></tr></thead><tbody><tr><td>钻石（前10%）</td><td>限定称号 + 赛季限定外观 + 大量荣誉点</td></tr><tr><td>黄金（前30%）</td><td>赛季外观 + 荣誉点</td></tr><tr><td>白银（前60%）</td><td>荣誉点</td></tr><tr><td>青铜（参与奖）</td><td>少量荣誉点</td></tr></tbody></table><h3 id="荣誉点兑换" tabindex="-1">荣誉点兑换 <a class="header-anchor" href="#荣誉点兑换" aria-label="Permalink to &quot;荣誉点兑换&quot;">​</a></h3><p>荣誉点是PvP专属货币，可兑换：</p><ul><li>PvP专属装备</li><li>PvP强化卡片</li><li>外观道具</li><li>药水/消耗品</li></ul><h2 id="pvp属性推荐" tabindex="-1">PvP属性推荐 <a class="header-anchor" href="#pvp属性推荐" aria-label="Permalink to &quot;PvP属性推荐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职业</th><th>PvP优先属性</th><th>说明</th></tr></thead><tbody><tr><td>骑士</td><td>VIT &gt; DEF &gt; HP</td><td>站得住才能保护队友</td></tr><tr><td>巫师</td><td>MATK &gt; 冷却 &gt; MDEF</td><td>爆发优先</td></tr><tr><td>刺客</td><td>暴击 &gt; 攻速 &gt; 闪避</td><td>一击必杀</td></tr><tr><td>猎人</td><td>远程攻击 &gt; 暴击 &gt; 闪避</td><td>放风筝</td></tr><tr><td>牧师</td><td>HP &gt; 治疗量 &gt; 施法速度</td><td>活着才能奶</td></tr><tr><td>商人</td><td>STR &gt; VIT &gt; DEF</td><td>近战硬刚</td></tr></tbody></table><blockquote><p><strong>提示</strong>：PvP和PvE的配装思路完全不同，建议准备一套专门的PvP装备。刺客和法师在竞技场中表现亮眼，但需要较高的操作水平。</p></blockquote>',31)])])}const c=a(o,[["render",h]]);export{g as __pageData,c as default};
